      "ids": ["EFF-01"],
      "type": "resource",
      "description": "Focusing on a 30% reduction in travel time may lead to increased energy consumption if not paired with energy-efficient routing."
    },
    {
      "ids": ["SAF-02"],
      "type": "resource",
      "description": "Strict execution of MRM may conflict with protocols that optimize energy use during critical failures."
    },
    {
      "ids": ["RES-06"],
      "type": "resource",
      "description": "Prioritizing safety over energy efficiency during emergency maneuvers could lead to higher energy consumption."
